"""신규 보습 300턴의 수작업 사례 명세를 고정 계약으로 조립해요.

기존 답변을 생성 재료로 사용하지 않아요. 기존 가족명·분할만 계승해요.
모든 사실·질문·주장·제한은 아래 행별 명세에서 먼저 작성해요.
"""
from __future__ import annotations
import hashlib
import importlib.util
import json
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
COS = HERE.parents[4]
sys.path.insert(0, str(COS))
spec = importlib.util.spec_from_file_location("fixed_validator", COS / "scripts/validate_qlora_dataset.py")
validator = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = validator
spec.loader.exec_module(validator)
POOL = {x["evidence_ref"]: x for x in (json.loads(l) for l in (COS / "data/rag/chunks.jsonl").read_text(encoding="utf-8").splitlines())}
OLD = [json.loads(l) for l in (COS / "data/qlora/v2/qlora_solution_hold_v2.jsonl").read_text(encoding="utf-8").splitlines()]
SPLITS = {x["scenario_family_id"]: x["split"] for x in OLD}
GROUPS = []

def group(family, ref, slot, lines, *, hn=None, product=False):
    cases = [line.split("|") for line in lines.strip().splitlines() if line.strip()]
    assert len(cases) == 10, (family, len(cases))
    assert all(len(c) == 5 for c in cases), family
    GROUPS.append(dict(family="s2-moisturizing-" + family, ref="ref:moisturizing-" + ref,
                       slot=slot, cases=cases, hn=hn, product=product))

