HOLDS = []

def hold_group(family, lines):
    cases = [line.split("|") for line in lines.strip().splitlines() if line.strip()]
    assert len(cases) == 10 and all(len(c) == 4 for c in cases), family
    HOLDS.append(dict(family="s2-moisturizing-" + family, cases=cases))

