def hard_negative(family, index):
    short = family.removeprefix("s2-moisturizing-")
    if short in {"fixed-combo-study", "limited-duration-study", "metric-specific-base", "ceramide-spray-scope"}:
        return "clinical_restraint"
    if short in {"feel-not-moisture", "fabric-residue", "emollient-reach", "hydration-indicators"}:
        return "rag_distractor_ignore"
    if short == "other-subject-pg":
        return "negation_or_other_subject"
    if short == "aha-label-uncertainty" or (short == "glycerin-limits" and index == 5) or (short == "date-basis-pending" and index in {5, 7}):
        return "version_mismatch_or_unknown"
    if short == "occlusive-scope" and index == 5:
        return "negation_or_other_subject"
    if short == "workplace-protection-models" and index == 8:
        return "clinical_restraint"
    return None


def write_jsonl(path, rows):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8", newline="\n")


def build():
    assert len(GROUPS) == 23 and len(HOLDS) == 7
    rows, traces = [], []
    for group_index, g in enumerate(GROUPS):
        family, ref = g["family"], g["ref"]
        short = family.removeprefix("s2-moisturizing-")
        for j, (fact, question, guidance, reason, limit) in enumerate(g["cases"]):
            rid = f"syn-sol-{921 + group_index * 10 + j:04d}"
            obs = {g["slot"]: slot(g["slot"], fact),
                   "constraints.requested_check": slot("constraints.requested_check", question),
                   "constraints.decision_context": slot("constraints.decision_context", "review_moisture_context")}
            # 미제공 제품 수치는 None/unknown으로 보존해요. 표시가 없는 제품을 만들지 않아요.
            products = []
            label = LABELS.get(short, [None] * 10)[j]
            if label:
                labels = label if isinstance(label, list) else [label]
                for product_index, product_label in enumerate(labels, 1):
                    product_id = f"syn-add900-m-{group_index + 1:02d}-{j + 1:02d}"
                    if len(labels) > 1:
                        product_id += f"-{product_index}"
                    products.append({"product_id": product_id,
                                     "version": "fixture-1", "synthetic_product": True,
                                     "status": "verified", "label_guidance": product_label})
            hn = hard_negative(family, j)
            if short == "aha-label-uncertainty":
                products.append({"product_id": f"syn-add900-active-{j + 1:02d}", "version": "unknown",
                                 "synthetic_product": True, "status": "unknown", "label_guidance": None,
                                 "active_ingredients": None, "concentrations": None, "ph": None})
            if short == "glycerin-limits" and j == 5:
                products[0]["concentrations"] = None
            if short == "date-basis-pending" and j in {5, 7}:
                obs["method.current_product_version"] = slot("method.current_product_version", None, state="unknown")
            if short == "other-subject-pg":
                obs["skin.other_person_report_separate"] = slot("skin.other_person_report_separate", True)
            for product in products:
                product["evidence_ref"] = f"catalog:{product['product_id']}@{product['version']}"
            chunks = [POOL[ref]]
            distractors = []
            if hn == "rag_distractor_ignore":
                distractors = ["ref:sun_protection-010"]
                chunks.append(POOL[distractors[0]])
            req = {"mode": "solution", "confirmed_observations": obs, "product_evidence": products,
                   "rag_chunks": chunks, "allowed_evidence_refs": [ref], "distractor_refs": distractors}
            answer = f"### 핵심 안내\n{guidance}\n\n### 근거 및 이유\n{reason} [{ref}].\n\n### 확인이 필요한 한계\n{limit}"
            row = make_row(rid, family, SPLITS[family], req, answer, hn)
            rows.append(row)
            traces.append({"row_id": rid, "scenario_family_id": family, "scenario_concept": question,
                           "input_fact_quote": fact, "input_fact_slot": g["slot"],
                           "product_evidence_fixture": products,
                           "requested_check": question, "guidance_quote": guidance,
                           "reference_quote": POOL[ref]["text"], "explanation_quote": reason,
                           "limitations_quote": limit, "reference_ref": ref,
                           "connection": "입력의 확인된 사실 범위에서 요청을 설명하고, 일반 원리는 허용 문헌에 연결해요. 개인의 측정 결과나 미확인 성분을 문헌으로 채우지 않아요.",
                           "review_status": "generator_self_check_only", "human_review": "unreviewed"})
    holds = []
    for group_index, g in enumerate(HOLDS):
        for j, (fact, reason, next_step, limit) in enumerate(g["cases"]):
            rid = f"syn-hold-{281 + group_index * 10 + j:04d}"
            obs = {"storage.confirmed_change": slot("storage.confirmed_change", fact),
                   "constraints.decision_context": slot("constraints.decision_context", "confirm_product_quality")}
            # 한 종류 변화가 확인됐다는 사실만으로 다른 변화의 부재를 만들지 않아요.
            # 부분 관찰은 확인된 세부 슬롯만 사용해요.
            if g["family"].endswith("new-odor"):
                obs["storage.new_odor_confirmed"] = slot("storage.new_odor_confirmed", True)
            elif g["family"].endswith("new-separation"):
                obs["storage.new_separation_confirmed"] = slot("storage.new_separation_confirmed", True)
            req = {"mode": "hold", "confirmed_observations": obs, "product_evidence": [], "rag_chunks": [],
                   "allowed_evidence_refs": [], "distractor_refs": []}
            answer = f"### 개별 권고 보류 안내\n{reason} {limit}\n\n### 필요한 다음 단계\n{next_step}"
            holds.append(make_row(rid, g["family"], SPLITS[g["family"]], req, answer, None))
            traces.append({"row_id": rid, "scenario_family_id": g["family"], "scenario_concept": fact,
                           "input_fact_quote": fact, "input_fact_slot": "storage.confirmed_change",
                           "hold_reason_quote": reason, "next_step_quote": next_step,
                           "limitations_quote": limit, "reference_ref": None,
                           "connection": "현재 입력의 제품 상태 문제를 그대로 보류 이유와 담당자 확인에 연결하며 제품·세안·도포 지시는 만들지 않아요.",
                           "review_status": "generator_self_check_only", "human_review": "unreviewed"})
    assert len(rows) == 230 and len(holds) == 70
    for i in range(10):
        batch = rows[i * 23:(i + 1) * 23] + holds[i * 7:(i + 1) * 7]
        write_jsonl(HERE.parent / "batches" / f"moisturizing_{i + 1:02d}.jsonl", batch)
    write_jsonl(HERE / "moisturizing_fact_trace.jsonl", traces)
    counts = {"total": 300, "solution": len(rows), "hold": len(holds),
              "train": sum(r["split"] == "train" for r in rows + holds),
              "val_internal": sum(r["split"] == "val_internal" for r in rows + holds),
              "hard_negative": sum(r["is_hard_negative"] for r in rows + holds),
              "english_relevant_solution": sum(validator._is_english_text(POOL[json.loads(r["messages"][1]["content"])["allowed_evidence_refs"][0]]["text"]) for r in rows),
              "generator_model": "gpt-6", "critic_status": "unreviewed", "human_review": "unreviewed"}
    (HERE / "moisturizing_generation_receipt.json").write_text(json.dumps(counts, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps(counts, ensure_ascii=False))


def make_row(rid, family, split, req, answer, hn):
    return {"id": rid, "scenario_id": "additional900-" + rid, "scenario_family_id": family,
            "group_id": family, "split": split, "mode": req["mode"],
            "domains": ["moisturizing"] if req["mode"] == "solution" else ["general_safety"],
            "card_ids": [], "is_hard_negative": hn is not None, "hard_negative_type": hn,
            "chunk_origins": {c["evidence_ref"]: "reference_excerpt" for c in req["rag_chunks"]},
            "allowed_evidence_refs": req["allowed_evidence_refs"], "distractor_refs": req["distractor_refs"],
            "scenario_concept": req["confirmed_observations"].get("constraints.requested_check", {}).get("value", req["confirmed_observations"].get("storage.confirmed_change", {}).get("value")),
            "runtime_invariants": {"mode": "development_preview", "production_enabled": False, "requires_approval": True, "saved": False},
            "provenance": {"source_origin": "new_synthetic", "source_scenario_id": None, "source_turn_id": None,
                           "generator_model": "gpt-6", "critic_model": None, "critic_status": "unreviewed", "human_review": "unreviewed"},
            "messages": [{"role": "system", "content": validator.SYSTEM_PROMPT_SOLUTION_HOLD},
                         {"role": "user", "content": json.dumps(req, ensure_ascii=False)},
                         {"role": "assistant", "content": answer}]}


if __name__ == "__main__":
    build()
